(906,1664,$mw$0B34864424711AA39CB584CFDD7E30A1DFB60FC7473C0B0A8302863AE7FCC8FC$mw$,$mw$cdb8dbd0831e0a1520d220ae9eb09c28$mw$,$mw$$mw$,$mw${"Id":1664,"StageId":3,"CategoryId":87,"Points":10,"TitleAr":"إذا كان u=(2,-3) وv=(-5,4)، فما المتجه u+v؟","TitleEn":"If u=(2,-3) and v=(-5,4), what is u+v?","QuestionTextAr":"إذا كان u=(2,-3) وv=(-5,4)، فما المتجه u+v؟","QuestionTextEn":"If u=(2,-3) and v=(-5,4), what is u+v?","DetailedSolutionAr":"القانون المستخدم: قانون جمع المتجهات: (a,b) + (c,d) = (a+c,b+d).\n\nخطوات الحل: نجمع المركبات المناظرة: ‏(2-5,-3+4)=(-3,1).","DetailedSolutionEn":"Rule used: Vector addition: (a,b) + (c,d) = (a+c,b+d).\n\nSolution steps: Add corresponding components: (2-5, -3+4) = (-3,1).","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6645,"Order":1,"LatexCode":"(-3,1)","IsCorrect":true},{"Id":6646,"Order":2,"LatexCode":"(7,-7)","IsCorrect":false},{"Id":6647,"Order":3,"LatexCode":"(-7,1)","IsCorrect":false},{"Id":6648,"Order":4,"LatexCode":"(3,-1)","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"اجمع على كل محور بشكل مستقل.","En":"Add independently along each axis."},{"Ar":"اجمع السينات معاً والصادات معاً مع مراعاة الإشارات.","En":"Add x-components and y-components separately, preserving signs."}],"Title":{"Ar":"إذا كان u=(2,-3) وv=(-5,4)، فما المتجه u+v؟","En":"If u=(2,-3) and v=(-5,4), what is u+v?"},"Points":10,"Options":[{"LatexCode":"(-3,1)","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"(7,-7)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"(7,−7) يمثل u−v لا u+v.","En":"(7,−7) is u−v, not u+v."}},{"LatexCode":"(-7,1)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"(−7,1) يغير إشارة مركبة x الأولى.","En":"(−7,1) changes the sign of the first x-component."}},{"LatexCode":"(3,-1)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"(3,−1) هو معاكس المجموع الصحيح.","En":"(3,−1) is the negative of the correct sum."}}],"StageId":3,"Question":{"Ar":"إذا كان u=(2,-3) وv=(-5,4)، فما المتجه u+v؟","En":"If u=(2,-3) and v=(-5,4), what is u+v?"},"Solution":{"Idea":{"Ar":"نجمع المتجهات بجمع المركبات المتناظرة.","En":"Add vectors component by component."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نجمع مركبتي x معاً ومركبتي y معاً.","En":"Add the x-components together and the y-components together."},{"Ar":"$(2+(-5),-3+4)$","En":"$(2+(-5),-3+4)$"},{"Ar":"نراعي إشارات الأعداد: 2−5=−3 و−3+4=1.","En":"Preserve signs: 2−5=−3 and −3+4=1."}],"Result":{"Ar":"$(-3,1)$","En":"$(-3,1)$"},"CommonError":{"Ar":"لا تجمع مركبات من محورين مختلفين.","En":"Do not combine components from different axes."},"FormulaLatex":"u+v=(u_x+v_x,u_y+v_y)","Substitution":{"Ar":"$(-3,1)$","En":"$(-3,1)$"},"Verification":{"Ar":"$(-3,1)-(-5,4)=(2,-3)$","En":"$(-3,1)-(-5,4)=(2,-3)$"}},"TrackIds":[10],"CategoryId":87,"PrimarySkillId":340,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"اجمع على كل محور بشكل مستقل.","En":"Add independently along each axis."},{"Ar":"اجمع السينات معاً والصادات معاً مع مراعاة الإشارات.","En":"Add x-components and y-components separately, preserving signs."}],"Solution":{"Idea":{"Ar":"نجمع المتجهات بجمع المركبات المتناظرة.","En":"Add vectors component by component."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نجمع مركبتي x معاً ومركبتي y معاً.","En":"Add the x-components together and the y-components together."},{"Ar":"$(2+(-5),-3+4)$","En":"$(2+(-5),-3+4)$"},{"Ar":"نراعي إشارات الأعداد: 2−5=−3 و−3+4=1.","En":"Preserve signs: 2−5=−3 and −3+4=1."}],"Result":{"Ar":"$(-3,1)$","En":"$(-3,1)$"},"CommonError":{"Ar":"لا تجمع مركبات من محورين مختلفين.","En":"Do not combine components from different axes."},"FormulaLatex":"u+v=(u_x+v_x,u_y+v_y)","Substitution":{"Ar":"$(-3,1)$","En":"$(-3,1)$"},"Verification":{"Ar":"$(-3,1)-(-5,4)=(2,-3)$","En":"$(-3,1)-(-5,4)=(2,-3)$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"(7,−7) يمثل u−v لا u+v.","En":"(7,−7) is u−v, not u+v."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"(−7,1) يغير إشارة مركبة x الأولى.","En":"(−7,1) changes the sign of the first x-component."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"(3,−1) هو معاكس المجموع الصحيح.","En":"(3,−1) is the negative of the correct sum."},"Order":4}]}$mw$,$mw$نجمع المتجهات بجمع المركبات المتناظرة.

$u+v=(u_x+v_x,u_y+v_y)$

1. نجمع مركبتي x معاً ومركبتي y معاً.

2. $(2+(-5),-3+4)$

3. نراعي إشارات الأعداد: 2−5=−3 و−3+4=1.

$(-3,1)$

$(-3,1)$ بلا وحدة قياس

$(-3,1)-(-5,4)=(2,-3)$

لا تجمع مركبات من محورين مختلفين.$mw$,$mw$Add vectors component by component.

$u+v=(u_x+v_x,u_y+v_y)$

1. Add the x-components together and the y-components together.

2. $(2+(-5),-3+4)$

3. Preserve signs: 2−5=−3 and −3+4=1.

$(-3,1)$

$(-3,1)$ Dimensionless

$(-3,1)-(-5,4)=(2,-3)$

Do not combine components from different axes.$mw$),
(907,1665,$mw$D3A6CF1C64BA3F479EDE491773E04E8B1A7A208E4B760C3EF9A968CB4B56593F$mw$,$mw$d743b5a5d35264c265b9da6c32a79fce$mw$,$mw$$mw$,$mw${"Id":1665,"StageId":3,"CategoryId":87,"Points":10,"TitleAr":"ما مقدار المتجه (5,12) في المستوى الإقليدي؟","TitleEn":"What is the Euclidean magnitude of the vector (5,12)?","QuestionTextAr":"ما مقدار المتجه (5,12) في المستوى الإقليدي؟","QuestionTextEn":"What is the Euclidean magnitude of the vector (5,12)?","DetailedSolutionAr":"القانون المستخدم: قانون المقدار الإقليدي: |v| = √(x² + y²).\n\nخطوات الحل: باستخدام فيثاغورس: الجذر التربيعي لـ(25+144)=الجذر التربيعي لـ169=13.","DetailedSolutionEn":"Rule used: Euclidean norm: |v| = √(x² + y²).\n\nSolution steps: By Pythagoras, the length is sqrt(5²+12²)=sqrt(169)=13.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6649,"Order":1,"LatexCode":"12","IsCorrect":false},{"Id":6650,"Order":2,"LatexCode":"13","IsCorrect":true},{"Id":6651,"Order":3,"LatexCode":"15","IsCorrect":false},{"Id":6652,"Order":4,"LatexCode":"17","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"استعمل قانون المعيار الإقليدي.","En":"Use the Euclidean norm formula."},{"Ar":"ربّع كل مركبة واجمع ثم خذ الجذر الموجب.","En":"Square each component, add, and take the positive root."}],"Title":{"Ar":"ما مقدار المتجه (5,12) في المستوى الإقليدي؟","En":"What is the Euclidean magnitude of the vector (5,12)?"},"Points":10,"Options":[{"LatexCode":"12","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"12 المركبة الرأسية فقط.","En":"Twelve is only the vertical component."}},{"LatexCode":"13","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"15","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"15 مربعه 225 لا 169.","En":"Fifteen squared is 225, not 169."}},{"LatexCode":"17","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"17 مجموع المركبتين وليس الطول الإقليدي.","En":"Seventeen adds the components instead of finding Euclidean length."}}],"StageId":3,"Question":{"Ar":"ما مقدار المتجه (5,12) في المستوى الإقليدي؟","En":"What is the Euclidean magnitude of the vector (5,12)?"},"Solution":{"Idea":{"Ar":"المعيار الإقليدي هو طول المتجه ويُحسب بفيثاغورس.","En":"The Euclidean norm is vector length, calculated using Pythagoras."},"Unit":{"Ar":"وحدة طول","En":"Length units"},"Steps":[{"Ar":"مركبتا المتجه متعامدتان في المستوى الإقليدي، فيطبق قانون فيثاغورس.","En":"The components are perpendicular in the Euclidean plane, so Pythagoras applies."},{"Ar":"$\\sqrt{5^2+12^2}=\\sqrt{25+144}$","En":"$\\sqrt{5^2+12^2}=\\sqrt{25+144}$"},{"Ar":"نجمع مربعي المركبتين ثم نأخذ الجذر غير السالب.","En":"Add squared components and take the nonnegative square root."}],"Result":{"Ar":"$13$","En":"$13$"},"CommonError":{"Ar":"لا تجمع المركبتين مباشرة بدلاً من جمع مربعيهما.","En":"Do not add components directly instead of their squares."},"FormulaLatex":"\\|v\\|_2=\\sqrt{v_x^2+v_y^2}","Substitution":{"Ar":"$\\sqrt{169}=13$","En":"$\\sqrt{169}=13$"},"Verification":{"Ar":"$13^2=5^2+12^2$","En":"$13^2=5^2+12^2$"}},"TrackIds":[10],"CategoryId":87,"PrimarySkillId":339,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"استعمل قانون المعيار الإقليدي.","En":"Use the Euclidean norm formula."},{"Ar":"ربّع كل مركبة واجمع ثم خذ الجذر الموجب.","En":"Square each component, add, and take the positive root."}],"Solution":{"Idea":{"Ar":"المعيار الإقليدي هو طول المتجه ويُحسب بفيثاغورس.","En":"The Euclidean norm is vector length, calculated using Pythagoras."},"Unit":{"Ar":"وحدة طول","En":"Length units"},"Steps":[{"Ar":"مركبتا المتجه متعامدتان في المستوى الإقليدي، فيطبق قانون فيثاغورس.","En":"The components are perpendicular in the Euclidean plane, so Pythagoras applies."},{"Ar":"$\\sqrt{5^2+12^2}=\\sqrt{25+144}$","En":"$\\sqrt{5^2+12^2}=\\sqrt{25+144}$"},{"Ar":"نجمع مربعي المركبتين ثم نأخذ الجذر غير السالب.","En":"Add squared components and take the nonnegative square root."}],"Result":{"Ar":"$13$","En":"$13$"},"CommonError":{"Ar":"لا تجمع المركبتين مباشرة بدلاً من جمع مربعيهما.","En":"Do not add components directly instead of their squares."},"FormulaLatex":"\\|v\\|_2=\\sqrt{v_x^2+v_y^2}","Substitution":{"Ar":"$\\sqrt{169}=13$","En":"$\\sqrt{169}=13$"},"Verification":{"Ar":"$13^2=5^2+12^2$","En":"$13^2=5^2+12^2$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"12 المركبة الرأسية فقط.","En":"Twelve is only the vertical component."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"15 مربعه 225 لا 169.","En":"Fifteen squared is 225, not 169."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"17 مجموع المركبتين وليس الطول الإقليدي.","En":"Seventeen adds the components instead of finding Euclidean length."},"Order":4}]}$mw$,$mw$المعيار الإقليدي هو طول المتجه ويُحسب بفيثاغورس.

$\|v\|_2=\sqrt{v_x^2+v_y^2}$

1. مركبتا المتجه متعامدتان في المستوى الإقليدي، فيطبق قانون فيثاغورس.

2. $\sqrt{5^2+12^2}=\sqrt{25+144}$

3. نجمع مربعي المركبتين ثم نأخذ الجذر غير السالب.

$\sqrt{169}=13$

$13$ وحدة طول

$13^2=5^2+12^2$

لا تجمع المركبتين مباشرة بدلاً من جمع مربعيهما.$mw$,$mw$The Euclidean norm is vector length, calculated using Pythagoras.

$\|v\|_2=\sqrt{v_x^2+v_y^2}$

1. The components are perpendicular in the Euclidean plane, so Pythagoras applies.

2. $\sqrt{5^2+12^2}=\sqrt{25+144}$

3. Add squared components and take the nonnegative square root.

$\sqrt{169}=13$

$13$ Length units

$13^2=5^2+12^2$

Do not add components directly instead of their squares.$mw$),
(908,1666,$mw$15B837A3335A62B69F269098A8A596B228765CC7221BBFD8E94B4F233CB2CBEF$mw$,$mw$8896e374f5547cfa8d315b309b48ad73$mw$,$mw$$mw$,$mw${"Id":1666,"StageId":3,"CategoryId":87,"Points":10,"TitleAr":"متجه مركبتاه (-6,8). كم يبلغ طوله باستخدام قانون مقدار المتجه؟","TitleEn":"A vector has components (-6,8). Find its magnitude using the vector norm formula.","QuestionTextAr":"متجه مركبتاه (-6,8). كم يبلغ طوله باستخدام قانون مقدار المتجه؟","QuestionTextEn":"A vector has components (-6,8). Find its magnitude using the vector norm formula.","DetailedSolutionAr":"القانون المستخدم: قانون المقدار الإقليدي: |v| = √(x² + y²)، وتُربّع المركبات السالبة أيضاً.\n\nخطوات الحل: مربع -6 يساوي 36 ومربع 8 يساوي 64؛ الجذر التربيعي لمجموعهما 100 يساوي 10.","DetailedSolutionEn":"Rule used: Euclidean norm: |v| = √(x² + y²), including squares of negative components.\n\nSolution steps: Square both components: 36+64=100; the square root is 10.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6653,"Order":1,"LatexCode":"8","IsCorrect":false},{"Id":6654,"Order":2,"LatexCode":"10","IsCorrect":true},{"Id":6655,"Order":3,"LatexCode":"12","IsCorrect":false},{"Id":6656,"Order":4,"LatexCode":"14","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"استعمل قانون المعيار الإقليدي.","En":"Use the Euclidean norm formula."},{"Ar":"ربّع كل مركبة واجمع ثم خذ الجذر الموجب.","En":"Square each component, add, and take the positive root."}],"Title":{"Ar":"متجه مركبتاه (-6,8). كم يبلغ طوله باستخدام قانون مقدار المتجه؟","En":"A vector has components (-6,8). Find its magnitude using the vector norm formula."},"Points":10,"Options":[{"LatexCode":"8","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"8 يهمل المركبة الأفقية.","En":"Eight ignores the horizontal component."}},{"LatexCode":"10","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"12","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"12 مربعه 144 لا 100.","En":"Twelve squared is 144, not 100."}},{"LatexCode":"14","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"14 مجموع القيم المطلقة لا المعيار الإقليدي.","En":"Fourteen is the sum of magnitudes, not the Euclidean norm."}}],"StageId":3,"Question":{"Ar":"متجه مركبتاه (-6,8). كم يبلغ طوله باستخدام قانون مقدار المتجه؟","En":"A vector has components (-6,8). Find its magnitude using the vector norm formula."},"Solution":{"Idea":{"Ar":"المعيار الإقليدي هو طول المتجه ويُحسب بفيثاغورس.","En":"The Euclidean norm is vector length, calculated using Pythagoras."},"Unit":{"Ar":"وحدة طول","En":"Length units"},"Steps":[{"Ar":"نربع المركبتين، وتربيع −6 يعطي 36 لا −36.","En":"Square both components; squaring −6 yields 36, not −36."},{"Ar":"$\\sqrt{(-6)^2+8^2}=\\sqrt{36+64}$","En":"$\\sqrt{(-6)^2+8^2}=\\sqrt{36+64}$"},{"Ar":"نجمع 36 و64 ثم نأخذ الجذر غير السالب.","En":"Add 36 and 64, then take the nonnegative square root."}],"Result":{"Ar":"$10$","En":"$10$"},"CommonError":{"Ar":"تربيع العدد السالب يعطي قيمة موجبة؛ والطول لا يكون سالباً.","En":"Squaring a negative gives a positive value; length cannot be negative."},"FormulaLatex":"\\|v\\|_2=\\sqrt{v_x^2+v_y^2}","Substitution":{"Ar":"$\\sqrt{100}=10$","En":"$\\sqrt{100}=10$"},"Verification":{"Ar":"$10^2=36+64$","En":"$10^2=36+64$"}},"TrackIds":[10],"CategoryId":87,"PrimarySkillId":339,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"استعمل قانون المعيار الإقليدي.","En":"Use the Euclidean norm formula."},{"Ar":"ربّع كل مركبة واجمع ثم خذ الجذر الموجب.","En":"Square each component, add, and take the positive root."}],"Solution":{"Idea":{"Ar":"المعيار الإقليدي هو طول المتجه ويُحسب بفيثاغورس.","En":"The Euclidean norm is vector length, calculated using Pythagoras."},"Unit":{"Ar":"وحدة طول","En":"Length units"},"Steps":[{"Ar":"نربع المركبتين، وتربيع −6 يعطي 36 لا −36.","En":"Square both components; squaring −6 yields 36, not −36."},{"Ar":"$\\sqrt{(-6)^2+8^2}=\\sqrt{36+64}$","En":"$\\sqrt{(-6)^2+8^2}=\\sqrt{36+64}$"},{"Ar":"نجمع 36 و64 ثم نأخذ الجذر غير السالب.","En":"Add 36 and 64, then take the nonnegative square root."}],"Result":{"Ar":"$10$","En":"$10$"},"CommonError":{"Ar":"تربيع العدد السالب يعطي قيمة موجبة؛ والطول لا يكون سالباً.","En":"Squaring a negative gives a positive value; length cannot be negative."},"FormulaLatex":"\\|v\\|_2=\\sqrt{v_x^2+v_y^2}","Substitution":{"Ar":"$\\sqrt{100}=10$","En":"$\\sqrt{100}=10$"},"Verification":{"Ar":"$10^2=36+64$","En":"$10^2=36+64$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"8 يهمل المركبة الأفقية.","En":"Eight ignores the horizontal component."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"12 مربعه 144 لا 100.","En":"Twelve squared is 144, not 100."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"14 مجموع القيم المطلقة لا المعيار الإقليدي.","En":"Fourteen is the sum of magnitudes, not the Euclidean norm."},"Order":4}]}$mw$,$mw$المعيار الإقليدي هو طول المتجه ويُحسب بفيثاغورس.

$\|v\|_2=\sqrt{v_x^2+v_y^2}$

1. نربع المركبتين، وتربيع −6 يعطي 36 لا −36.

2. $\sqrt{(-6)^2+8^2}=\sqrt{36+64}$

3. نجمع 36 و64 ثم نأخذ الجذر غير السالب.

$\sqrt{100}=10$

$10$ وحدة طول

$10^2=36+64$

تربيع العدد السالب يعطي قيمة موجبة؛ والطول لا يكون سالباً.$mw$,$mw$The Euclidean norm is vector length, calculated using Pythagoras.

$\|v\|_2=\sqrt{v_x^2+v_y^2}$

1. Square both components; squaring −6 yields 36, not −36.

2. $\sqrt{(-6)^2+8^2}=\sqrt{36+64}$

3. Add 36 and 64, then take the nonnegative square root.

$\sqrt{100}=10$

$10$ Length units

$10^2=36+64$

Squaring a negative gives a positive value; length cannot be negative.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
